def sql_unquote_identifier(s: str) -> str:
    s = s.strip()
    if len(s) >= 2 and ((s[0] == s[-1] == '"') or (s[0] == s[-1] == '`') or (s[0] == s[-1] == '[' and s[-1] == ']')):
        return s[1:-1].replace('""', '"')
    return s


def quote_ident(name: str) -> str:
    if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
        return name
    return '"' + name.replace('"', '""') + '"'


def sqlite_quote_string(value: str) -> str:
    return "'" + value.replace("'", "''") + "'"


def map_declared_type(decl: Optional[str]) -> str:
    if not decl:
        return "varchar"
    d = decl.strip().lower()
    d = re.sub(r"\s+", " ", d)
    # Remove SQLite/DuckDB constraints that can leak into type strings in simple parsing.
    d = re.split(r"\s+(?:primary|not|null|default|unique|check|references)\b", d)[0].strip()
    if not d:
        return "varchar"
    if d.startswith("tinyint") or d == "int1":
        return "int8"
    if d.startswith("smallint") or d == "int2":
        return "int16"
    if d in ("int", "integer", "signed", "int4") or d.startswith("integer") or d.startswith("int("):
        return "int32"
    if d.startswith("bigint") or d == "int8":
        return "int64"
    if d.startswith("hugeint") or d.startswith("int128"):
        return "int128"
    if d.startswith("u") and "int" in d:
        if "big" in d or "64" in d:
            return "uint64"
        return "uint32"
    if d.startswith("bool"):
        return "boolean"
    if d.startswith("varchar") or d.startswith("char") or d.startswith("text") or d.startswith("string"):
        return "varchar"
    if d.startswith("double"):
        return "double"
    if d.startswith("float") or d.startswith("real"):
        return "float" if d.startswith("float") else "double"
    if d.startswith("decimal") or d.startswith("numeric"):
        m = re.search(r"\(([^)]+)\)", d)
        return f"decimal({m.group(1).replace(' ', '')})" if m else "decimal"
    if d.startswith("date"):
        return "date"
    if d.startswith("timestamp") or d.startswith("datetime"):
        return "timestamp"
    if d.startswith("time"):
        return "time"
    if d.startswith("blob") or d.startswith("bytea"):
        return "blob"
    return d.upper() if d in ("uuid",) else d


def type_is_numeric(t: str) -> bool:
    low = (t or "").lower()
    if low.startswith("decimal") or low.startswith("numeric"):
        return True
    return low in NUMERIC_TYPES or low.startswith("int") or low.startswith("uint")


def type_is_bool(t: str) -> bool:
    return (t or "").lower() == "boolean"


def type_is_textual(t: str) -> bool:
    low = (t or "").lower()
    return low in ("varchar", "text", "string", "date", "time", "timestamp", "blob") or low.startswith("varchar")


def infer_type_from_value(value: Any) -> str:
    if value is None:
        return "int32"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "int32" if -2147483648 <= value <= 2147483647 else "int64"
    if isinstance(value, float):
        return "double"
    if isinstance(value, (bytes, bytearray, memoryview)):
        return "blob"
    return "varchar"


def normalize_int_type_for_literal(num: str) -> str:
    try:
        v = int(num.replace("_", ""))
    except Exception:
        return "int64"
    return "int32" if -2147483648 <= v <= 2147483647 else "int64"


def decimal_type_for_literal(lit: str) -> str:
    s = lit.strip().replace("_", "")
    if "e" in s.lower():
        return "double"
    if "." in s:
        before, after = s.split(".", 1)
        before = before.lstrip("+-")
        precision = len(before.lstrip("0")) + len(after)
        if before.strip("0") == "":
            precision = max(1, len(after))
        scale = len(after)
        return f"decimal({max(1, precision)},{scale})"
    return normalize_int_type_for_literal(s)


def duck_type_from_cast(t: str) -> str:
    return map_declared_type(t)


def split_top_level_commas(s: str) -> List[str]:
    parts: List[str] = []
    start = 0
    depth = 0
    in_single = False
    in_double = False
    in_bracket = False
    i = 0
    while i < len(s):
        c = s[i]
        if in_single:
            if c == "'":
                if i + 1 < len(s) and s[i + 1] == "'":
                    i += 1
                else:
                    in_single = False
        elif in_double:
            if c == '"':
                if i + 1 < len(s) and s[i + 1] == '"':
                    i += 1
                else:
                    in_double = False
        elif in_bracket:
            if c == ']':
                in_bracket = False
        else:
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c == '[':
                in_bracket = True
                depth += 1
            elif c in "({":
                depth += 1
            elif c in ")}":
                depth = max(0, depth - 1)
            elif c == ',' and depth == 0:
                parts.append(s[start:i].strip())
                start = i + 1
        i += 1
    tail = s[start:].strip()
    if tail:
        parts.append(tail)
    return parts


def find_top_level_keyword(s: str, keyword: str, start_pos: int = 0) -> int:
    kw = keyword.lower()
    depth = 0
    in_single = in_double = False
    i = start_pos
    while i < len(s):
        c = s[i]
        if in_single:
            if c == "'":
                if i + 1 < len(s) and s[i + 1] == "'":
                    i += 1
                else:
                    in_single = False
        elif in_double:
            if c == '"':
                if i + 1 < len(s) and s[i + 1] == '"':
                    i += 1
                else:
                    in_double = False
        else:
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c in "([{" :
                depth += 1
            elif c in ")]}" :
                depth = max(0, depth - 1)
            elif depth == 0 and s[i:i+len(kw)].lower() == kw:
                before = s[i-1] if i > 0 else ' '
                after = s[i+len(kw)] if i + len(kw) < len(s) else ' '
                if not (before.isalnum() or before == '_') and not (after.isalnum() or after == '_'):
                    return i
        i += 1
    return -1


def parse_select_list(stmt: str) -> Optional[List[str]]:
    m = re.match(r"\s*select\s+(?:distinct\s+)?", stmt, flags=re.I | re.S)
    if not m:
        return None
    start = m.end()
    end = find_top_level_keyword(stmt, "from", start)
    if end < 0:
        # Stop at a set operation/order/limit if present.
        candidates = [len(stmt)]
        for kw in ("union", "order", "limit", "where", "group", "having"):
            p = find_top_level_keyword(stmt, kw, start)
            if p >= 0:
                candidates.append(p)
        end = min(candidates)
    return split_top_level_commas(stmt[start:end].strip())


def split_alias(expr: str) -> Tuple[str, Optional[str]]:
    s = expr.strip()
    # Explicit AS at top level.
    pos = -1
    depth = 0
    in_single = in_double = False
    i = 0
    while i < len(s):
        c = s[i]
        if in_single:
            if c == "'":
                if i + 1 < len(s) and s[i+1] == "'":
                    i += 1
                else:
                    in_single = False
        elif in_double:
            if c == '"':
                if i + 1 < len(s) and s[i+1] == '"':
                    i += 1
                else:
                    in_double = False
        else:
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c in "([{" :
                depth += 1
            elif c in ")]}" :
                depth = max(0, depth-1)
            elif depth == 0 and s[i:i+2].lower() == "as":
                before = s[i-1] if i else ' '
                after = s[i+2] if i+2 < len(s) else ' '
                if before.isspace() and after.isspace():
                    pos = i
        i += 1
    if pos >= 0:
        return s[:pos].strip(), sql_unquote_identifier(s[pos+2:].strip())
    # Trailing bare alias: expression alias. Avoid stealing binary operators/keywords.
    parts = shlex.split(s, posix=False)
    if len(parts) >= 2:
        alias = parts[-1]
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", alias) and parts[-2].lower() not in (
            "+", "-", "*", "/", "%", "=", "<", ">", "and", "or", "is", "not", "in", "like", "ilike"
        ):
            # Only if the preceding text is not a function call ending right before alias with no whitespace complexity.
            prefix = s[:s.rfind(alias)].rstrip()
            if prefix and not prefix.lower().endswith(("from", "where")):
                return prefix, alias
    return s, None


def generated_column_name(expr: str) -> str:
    expr = expr.strip()
    low = expr.lower()
    if low == "true":
        return "CAST('t' AS BOOLEAN)"
    if low == "false":
        return "CAST('f' AS BOOLEAN)"
    if low == "null":
        return "NULL"
    if re.fullmatch(r"[+-]?\d+", expr):
        return expr
    if re.fullmatch(r"[+-]?\d+\.\d+(?:e[+-]?\d+)?", expr, flags=re.I):
        return expr
    if re.fullmatch(r"'(?:''|[^'])*'", expr, flags=re.S):
        return expr
    if re.fullmatch(r"count\s*\(\s*\*\s*\)", expr, flags=re.I):
        return "count_star()"
    # Put spaces around common binary operators and wrap in parentheses for simple expressions.
    m = re.fullmatch(r"(.+?)\s*(=|<>|!=|<=|>=|<|>|\+|-|\*|/)\s*(.+)", expr, flags=re.S)
    if m and not expr.startswith("("):
        return f"({m.group(1).strip()} {m.group(2)} {m.group(3).strip()})"
    return re.sub(r"\s+", " ", expr)


def infer_type_from_expr(expr: str, rows: Sequence[Sequence[Any]], idx: int) -> str:
    original = expr.strip()
    e, _alias = split_alias(original)
    low = e.lower().strip()
    # Cast shorthand or CAST()
    m = re.search(r"::\s*([A-Za-z][A-Za-z0-9_]*(?:\s*\([^)]*\))?)", low)
    if m:
        return duck_type_from_cast(m.group(1))
    m = re.match(r"cast\s*\(.+?\s+as\s+([A-Za-z][A-Za-z0-9_]*(?:\s*\([^)]*\))?)\s*\)", low, flags=re.S)
    if m:
        return duck_type_from_cast(m.group(1))
    if low in ("true", "false"):
        return "boolean"
    if low == "null":
        return "int32"
    if re.fullmatch(r"'(?:''|[^'])*'", e, flags=re.S):
        return "varchar"
    if re.fullmatch(r"date\s*'(?:''|[^'])*'", low, flags=re.S):
        return "date"
    if re.fullmatch(r"time\s*'(?:''|[^'])*'", low, flags=re.S):
        return "time"
    if re.fullmatch(r"timestamp\s*'(?:''|[^'])*'", low, flags=re.S):
        return "timestamp"
    if re.fullmatch(r"[+-]?\d+", low):
        return normalize_int_type_for_literal(low)
    if re.fullmatch(r"[+-]?(?:\d+\.\d*|\d*\.\d+)(?:e[+-]?\d+)?", low, flags=re.I):
        return decimal_type_for_literal(low)
    if re.fullmatch(r"[+-]?\d+(?:\.\d+)?e[+-]?\d+", low, flags=re.I):
        return "double"
    if re.search(r"\b(count|count_if)\s*\(", low):
        return "int64"
    if re.search(r"\bsum\s*\(", low):
        return "int128"
    if re.search(r"\b(avg|mean|median|stddev|variance)\s*\(", low):
        return "double"
    if re.search(r"\b(length|strlen|regexp_count)\s*\(", low):
        return "int64"
    if re.search(r"\b(regexp_matches|contains|prefix|suffix)\s*\(", low) or re.search(r"\s(=|<>|!=|<|>|<=|>=|is\s+not|is)\s", low):
        return "boolean"
    if re.search(r"\b(upper|lower|substring|substr|concat|printf|format|version)\s*\(", low):
        return "varchar"
    if "/" in low:
        return "double"
    # Fall back to actual values.
    for row in rows:
        if idx < len(row) and row[idx] is not None:
            return infer_type_from_value(row[idx])
    return "int32"


def split_sql_statements(text: str) -> List[str]:
    statements: List[str] = []
    start = 0
    in_single = in_double = False
    line_comment = False
    block_comment = False
    i = 0
    while i < len(text):
        c = text[i]
        n = text[i+1] if i + 1 < len(text) else ''
        if line_comment:
            if c == '\n':
                line_comment = False
        elif block_comment:
            if c == '*' and n == '/':
                block_comment = False
                i += 1
        elif in_single:
            if c == "'":
                if n == "'":
                    i += 1
                else:
                    in_single = False
        elif in_double:
            if c == '"':
                if n == '"':
                    i += 1
                else:
                    in_double = False
        else:
            if c == '-' and n == '-':
                line_comment = True
                i += 1
            elif c == '/' and n == '*':
                block_comment = True
                i += 1
            elif c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c == ';':
                stmt = text[start:i].strip()
                if stmt:
                    statements.append(stmt + ';')
                start = i + 1
        i += 1
    tail = text[start:].strip()
    if tail:
        statements.append(tail)
    return statements


@dataclass
class Result:
    columns: List[str]
    types: List[str]
    rows: List[Tuple[Any, ...]]


class DuckShell:
    def __init__(self) -> None:
        self.mode = "duckbox"
        self.insert_table = "table"
        self.headers = True
        self.nullvalue = "NULL"
        self.colsep = "|"
        self.rowsep = "\n"
        self.echo = False
        self.bail = False
        self.safe = False
        self.readonly = False
        self.no_init = False
        self.batch = False
        self.interactive_forced = False
        self.changes = False
        self.timer = False
        self.exit_code = 0
        self.should_exit = False
        self.filename = ":memory:"
        self.db_display_name = "memory"
        self.conn: Optional[sqlite3.Connection] = None
        self.output: io.TextIOBase = sys.stdout
        self.output_name = "stdout"
        self.once_output: Optional[io.TextIOBase] = None
        self.last_result: Optional[Result] = None
        self._temp_counter = 0
        self._csv_temp_types: Dict[str, Dict[str, str]] = {}
        self.open_database(":memory:")

    def open_database(self, filename: str) -> None:
        if self.conn is not None:
            try:
                self.conn.commit()
                self.conn.close()
            except Exception:
                pass
        self.filename = filename or ":memory:"
        if self.filename in (":memory:", "", None):
            sqlite_name = ":memory:"
            self.db_display_name = "memory"
        else:
            sqlite_name = self.filename
            base = os.path.basename(self.filename)
            self.db_display_name = os.path.splitext(base)[0] or base
        uri = False
        if self.readonly and sqlite_name != ":memory:":
            # Open using SQLite read-only URI when possible; if the file does not exist this mirrors a failure.
            sqlite_name = f"file:{sqlite_name}?mode=ro"
            uri = True
        self.conn = sqlite3.connect(sqlite_name, uri=uri)
        self.conn.row_factory = sqlite3.Row
        self.register_functions()

    def register_functions(self) -> None:
        assert self.conn is not None
        self.conn.create_function("version", 0, lambda: VERSION)
        self.conn.create_function("duckdb_version", 0, lambda: VERSION)
        self.conn.create_function("current_database", 0, lambda: self.db_display_name)
        self.conn.create_function("regexp_matches", 2, lambda s, p: None if s is None or p is None else (1 if re.search(str(p), str(s)) else 0))
        self.conn.create_function("regexp_full_match", 2, lambda s, p: None if s is None or p is None else (1 if re.fullmatch(str(p), str(s)) else 0))
        self.conn.create_function("contains", 2, lambda s, sub: None if s is None or sub is None else (1 if str(sub) in str(s) else 0))
        self.conn.create_function("prefix", 2, lambda s, sub: None if s is None or sub is None else (1 if str(s).startswith(str(sub)) else 0))
        self.conn.create_function("suffix", 2, lambda s, sub: None if s is None or sub is None else (1 if str(s).endswith(str(sub)) else 0))
        self.conn.create_function("concat", -1, lambda *args: ''.join('' if x is None else str(x) for x in args))
        self.conn.create_function("ifnull", 2, lambda a, b: b if a is None else a)
        self.conn.create_function("isnan", 1, lambda x: 1 if isinstance(x, float) and math.isnan(x) else 0)
        self.conn.create_function("isinf", 1, lambda x: 1 if isinstance(x, float) and math.isinf(x) else 0)

    def write(self, text: str) -> None:
        out = self.once_output or self.output
        out.write(text)
        out.flush()
        if self.once_output is not None:
            try:
                self.once_output.close()
            except Exception:
                pass
            self.once_output = None

    def set_mode(self, mode: str, table: Optional[str] = None, from_cli: bool = False) -> bool:
        mode = mode.lower()
        aliases = {"lines": "line", "cols": "column", "tabs": "tabs"}
        mode = aliases.get(mode, mode)
        valid = {"ascii", "box", "column", "csv", "duckbox", "html", "insert", "json", "jsonlines", "latex", "line", "list", "markdown", "quote", "table", "tabs", "tcl", "trash"}
        if mode not in valid:
            eprint("Error: mode should be one of: ascii box column csv duckbox html insert json jsonlines latex line list markdown quote table tabs tcl trash ")
            self.exit_code = 1
            return False
        self.mode = mode
        if mode == "csv":
            self.colsep = ","
            self.rowsep = "\n" if from_cli else "\r\n"
        elif mode == "tabs":
            self.colsep = "\t"
            self.rowsep = "\n"
        elif mode == "list":
            self.colsep = "|"
            self.rowsep = "\n"
        elif mode == "ascii":
            self.colsep = "\x1f"
            self.rowsep = "\x1e"
        if table:
            self.insert_table = table
        return True

    def escape_sep(self, s: str) -> str:
        if s == "\n":
            return "\\n"
        if s == "\r\n":
            return "\\r\\n"
        if s == "\t":
            return "\\t"
        if s == "\x1f":
            return "\\037"
        if s == "\x1e":
            return "\\036"
        return s

    def show_settings(self) -> None:
        self.write(
            f"        echo: {'on' if self.echo else 'off'}\n"
            f"     headers: {'on' if self.headers else 'off'}\n"
            f"        mode: {self.mode}\n"
            f"   nullvalue: \"{self.nullvalue}\"\n"
            f"      output: {self.output_name}\n"
            f"colseparator: \"{self.escape_sep(self.colsep)}\"\n"
            f"rowseparator: \"{self.escape_sep(self.rowsep)}\"\n"
            f"       width: \n"
            f"    filename: {self.filename}\n"
        )

    def process_script(self, text: str, source_name: str = "stdin") -> bool:
        ok_all = True
        buffer = ""
        for raw_line in text.splitlines(True):
            line = raw_line.rstrip("\n")
            # Dot commands are line-oriented only when no SQL is pending.
            if not buffer.strip() and line.lstrip().startswith('.'):
                cmd = line.strip()
                if self.echo:
                    self.write(cmd + "\n")
                ok = self.execute_dot_command(cmd)
                ok_all = ok_all and ok
                if not ok and self.bail:
                    return False
                if self.should_exit:
                    return ok_all
                continue
            buffer += raw_line
            stmts = split_sql_statements(buffer)
            complete = buffer.rstrip().endswith(';')
            if complete:
                buffer = ""
            else:
                # Keep the last incomplete statement in the buffer.
                if stmts:
                    # If splitter returned one statement without a semicolon, preserve it.
                    if not stmts[-1].rstrip().endswith(';'):
                        buffer = stmts.pop()
                    else:
                        buffer = ""
            for stmt in stmts:
                if self.echo:
                    self.write(stmt.strip() + "\n")
                ok = self.execute_sql(stmt)
                ok_all = ok_all and ok
                if not ok and self.bail:
                    return False
                if self.should_exit:
                    return ok_all
        if buffer.strip() and not self.should_exit:
            stmt = buffer.strip()
            if self.echo:
                self.write(stmt + "\n")
            ok = self.execute_sql(stmt)
            ok_all = ok_all and ok
        return ok_all

    def execute_dot_command(self, line: str) -> bool:
        if not line.startswith('.'):
            return True
        try:
            parts = shlex.split(line[1:], posix=True)
        except ValueError:
            parts = line[1:].split()
        if not parts:
            return True
        cmd = parts[0]
        args = parts[1:]
        c = cmd.lower()
        try:
            if c in ("quit", "exit"):
                code = int(args[0]) if args else 0
                self.exit_code = code
                self.should_exit = True
                return True
            if c == "help":
                self.dot_help(args)
                return True
            if c == "version":
                self.write(f"{DOT_VERSION_LINE}\n{COMPILER_LINE}\n")
                return True
            if c == "about":
                self.write(
                    f"DuckDB {VERSION} ({CODENAME})\n\n"
                    "DuckDB is an in-process analytical database management system designed for fast execution of complex SQL queries. "
                    "It runs embedded within its host process with no external dependencies, and is optimized for OLAP workloads using a columnar, vectorized execution engine.\n\n"
                    "Developed and maintained by the DuckDB Foundation, available under the MIT License.\n"
                    "For more information, visit https://duckdb.org or https://github.com/duckdb/duckdb.\n"
                )
                return True
            if c == "show":
                self.show_settings()
                return True
            if c == "mode":
                if not args:
                    self.write(f"current output mode: {self.mode}\n")
                    return True
                table = args[1] if len(args) > 1 else None
                return self.set_mode(args[0], table, from_cli=False)
            if c in ("headers", "header"):
                if args:
                    self.headers = args[0].lower() in ("on", "yes", "true", "1")
                return True
            if c == "nullvalue":
                self.nullvalue = " ".join(args) if args else ""
                return True
            if c == "separator":
                if args:
                    self.colsep = self.decode_cli_sep(args[0])
                if len(args) > 1:
                    self.rowsep = self.decode_cli_sep(args[1])
                return True
            if c == "echo":
                if args:
                    self.echo = args[0].lower() in ("on", "yes", "true", "1")
                return True
            if c == "bail":
                if args:
                    self.bail = args[0].lower() in ("on", "yes", "true", "1")
                return True
            if c == "changes":
                if args:
                    self.changes = args[0].lower() in ("on", "yes", "true", "1")
                return True
            if c == "timer":
                if args:
                    self.timer = args[0].lower() in ("on", "yes", "true", "1")
                return True
            if c == "print":
                self.write(" ".join(args) + "\n")
                return True
            if c == "read":
                if not args:
                    eprint("Usage: .read FILE")
                    self.exit_code = 1
                    return False
                with open(args[0], "r", encoding="utf-8") as f:
                    return self.process_script(f.read(), args[0])
            if c == "open":
                if args:
                    # ignore .open options except --readonly/-readonly
                    files = [a for a in args if not a.startswith('-')]
                    self.readonly = any(a in ("--readonly", "-readonly") for a in args)
                    if files:
                        self.open_database(files[-1])
                else:
                    self.open_database(":memory:")
                return True
            if c == "output":
                if not args:
                    if self.output is not sys.stdout:
                        try:
                            self.output.close()
                        except Exception:
                            pass
                    self.output = sys.stdout
                    self.output_name = "stdout"
                else:
                    self.output = open(args[0], "w", encoding="utf-8", newline="")
                    self.output_name = args[0]
                return True
            if c == "once":
                if args:
                    self.once_output = open(args[0], "w", encoding="utf-8", newline="")
                return True
            if c in ("shell", "system"):
                if self.safe:
                    eprint(".sh/.system cannot be used in -safe mode")
                    self.exit_code = 1
                    return False
                if args:
                    rc = subprocess.call(args)
                    if rc != 0:
                        self.exit_code = rc
                        return False
                return True
            if c == "cd":
                if args:
                    os.chdir(args[0])
                return True
            if c == "tables":
                self.dot_tables(args[0] if args else None)
                return True
            if c == "schema":
                self.dot_schema(args[0] if args else None)
                return True
            if c == "indexes":
                self.dot_indexes(args[0] if args else None)
                return True
            if c == "dump":
                self.dot_dump(args[0] if args else None)
                return True
            if c == "databases":
                res = Result(["database_name", "database_file"], ["varchar", "varchar"], [(self.db_display_name, self.filename if self.filename != ":memory:" else "(memory)")])
                self.render_result(res)
                return True
            if c == "import":
                if len(args) < 2:
                    eprint("Usage: .import FILE TABLE")
                    self.exit_code = 1
                    return False
                self.import_csv(args[0], args[1])
                return True
            if c in ("safe_mode",):
                self.safe = True
                return True
            if c in ("columns", "rows", "multiline", "singleline", "highlight", "highlight_errors", "highlight_results", "render_errors", "render_completion", "read_line_version", "progress_bar", "pager", "width", "maxrows", "maxwidth", "decimal_sep", "thousand_sep", "large_number_rendering", "startup_text", "ui_command", "display_colors", "highlight_colors", "highlight_mode", "binary", "auto_format", "excel", "edit", "last", "prompt", "log"):
                # Mostly display/UI knobs; accept silently or with simple output.
                if c == "last" and self.last_result:
                    self.render_result(self.last_result)
                return True
            eprint(f"Unknown Command Error: Unrecognized command '{cmd}'\n")
            eprint('Did you mean: ".open"')
            eprint("Run '.help' for more information.")
            self.exit_code = 1
            return False
        except Exception as ex:
            eprint(f"Error: {ex}")
            self.exit_code = 1
            return False

    def decode_cli_sep(self, sep: str) -> str:
        if sep == r"\n":
            return "\n"
        if sep == r"\r\n":
            return "\r\n"
        if sep == r"\t":
            return "\t"
        return sep

    def dot_help(self, args: Sequence[str]) -> None:
        pattern = args[-1].lower() if args and not args[0].startswith('-') else None
        lines = [
            (".about", "", "Show information about DuckDB"),
            (".auto_format", "on|off", "Automatically format SQL before execution.  Default OFF"),
            (".bail", "on|off", "Stop after hitting an error.  Default OFF"),
            (".binary", "on|off", "Turn binary output on or off.  Default OFF"),
            (".cd", "DIRECTORY", "Change the working directory to DIRECTORY"),
            (".changes", "on|off", "Show number of rows changed by SQL"),
            (".columns", "", "Column-wise rendering of query results"),
            (".databases", "", "List names and files of attached databases"),
            (".dump", "?TABLE?", "Render database content as SQL"),
            (".echo", "on|off", "Turn command echo on or off"),
            (".exit", "?CODE?", "Exit this program with return-code CODE"),
            (".headers", "on|off", "Turn display of headers on or off"),
            (".help", "?-all? ?PATTERN?", "Show help text for PATTERN"),
            (".import", "FILE TABLE", "Import data from FILE into TABLE"),
            (".indexes", "?TABLE?", "Show names of indexes"),
            (".mode", "MODE ?TABLE?", "Set output mode"),
            (".nullvalue", "STRING", "Use STRING in place of NULL values"),
            (".open", "?OPTIONS? ?FILE?", "Close existing database and reopen FILE"),
            (".once", "?FILE?", "Output for the next SQL command only to FILE"),
            (".output", "?FILE?", "Send output to FILE or stdout if FILE is omitted"),
            (".print", "STRING...", "Print literal STRING"),
            (".quit", "", "Exit this program"),
            (".read", "FILE", "Read input from FILE"),
            (".schema", "?PATTERN?", "Show the CREATE statements matching PATTERN"),
            (".shell", "CMD ARGS...", "Run CMD ARGS... in a system shell"),
            (".show", "", "Show the current values for various settings"),
            (".system", "CMD ARGS...", "Run CMD ARGS... in a system shell"),
            (".tables", "?TABLE?", "List names of tables matching LIKE pattern TABLE"),
            (".timer", "on|off", "Turn SQL timer on or off"),
            (".version", "", "Show the version"),
            (".width", "NUM1 NUM2 ...", "Set minimum column widths for columnar output"),
        ]
        matched = False
        for name, usage, desc in lines:
            if pattern and pattern not in name.lower() and pattern not in desc.lower():
                continue
            matched = True
            self.write(f"{GREEN}{name}{RESET}{YELLOW} {usage}{RESET}".ljust(54 + len(GREEN+RESET+YELLOW+RESET)) + f"{desc}\n")
        if not matched and pattern:
            self.write(f"Nothing matches '{pattern}'\n")
        elif not pattern:
            self.write("\nRun .help --all for extended information\nRun .help shortcuts for keyboard shortcuts\n")

    def table_names(self) -> List[str]:
        assert self.conn is not None
        rows = self.conn.execute("SELECT name FROM sqlite_master WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%' ORDER BY name").fetchall()
        return [r[0] for r in rows if not str(r[0]).startswith("__duck_")]

    def get_table_info(self, table: str) -> List[sqlite3.Row]:
        assert self.conn is not None
        return self.conn.execute(f"PRAGMA table_info({quote_ident(table)})").fetchall()

    def dot_tables(self, pattern: Optional[str]) -> None:
        names = self.table_names()
        if pattern:
            pat = pattern.replace('%', '.*').replace('_', '.')
            names = [n for n in names if re.fullmatch(pat, n)]
        if not names:
            return
        # DuckDB renders this command specially; a compact sqlite-shell-like list is close for scripts.
        self.write("  ".join(names) + "\n")

    def dot_schema(self, pattern: Optional[str]) -> None:
        assert self.conn is not None
        rows = self.conn.execute("SELECT type,name,sql FROM sqlite_master WHERE type IN ('table','view','index') AND name NOT LIKE 'sqlite_%' ORDER BY type,name").fetchall()
        for r in rows:
            name = r[1]
            if pattern and pattern not in name:
                continue
            sql = r[2]
            if sql:
                self.write(self.normalize_schema_sql(sql) + ";\n")

    def normalize_schema_sql(self, sql: str) -> str:
        sql = re.sub(r"\bint\b", "INTEGER", sql, flags=re.I)
        sql = re.sub(r"\binteger\b", "INTEGER", sql, flags=re.I)
        sql = re.sub(r"\bvarchar\b", "VARCHAR", sql, flags=re.I)
        sql = re.sub(r"\btext\b", "VARCHAR", sql, flags=re.I)
        sql = re.sub(r"\breal\b", "DOUBLE", sql, flags=re.I)
        return sql

    def dot_indexes(self, pattern: Optional[str]) -> None:
        assert self.conn is not None
        sql = "SELECT name,tbl_name FROM sqlite_master WHERE type='index' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        for r in self.conn.execute(sql):
            if pattern and pattern not in r[1] and pattern not in r[0]:
                continue
            self.write(str(r[0]) + "\n")

    def dot_dump(self, pattern: Optional[str]) -> None:
        assert self.conn is not None
        self.write("BEGIN TRANSACTION;\n")
        for line in self.conn.iterdump():
            if line in ("BEGIN TRANSACTION;", "COMMIT;"):
                continue
            if pattern and pattern not in line:
                continue
            self.write(self.normalize_schema_sql(line) + ("\n" if line.endswith(';') else ";\n"))
        self.write("COMMIT;\n")

    def import_csv(self, path: str, table: str) -> None:
        cols, types, rows = read_csv_file(path)
        assert self.conn is not None
        self.conn.execute(f"DROP TABLE IF EXISTS {quote_ident(table)}")
        col_defs = ", ".join(f"{quote_ident(c)} {sqlite_type_for_duck(t)}" for c, t in zip(cols, types))
        self.conn.execute(f"CREATE TABLE {quote_ident(table)}({col_defs})")
        if rows:
            ph = ",".join("?" for _ in cols)
            self.conn.executemany(f"INSERT INTO {quote_ident(table)} VALUES({ph})", rows)
        self.conn.commit()

    def execute_sql(self, stmt: str) -> bool:
        stmt = stmt.strip()
        if not stmt:
            return True
        if stmt.endswith(';'):
            stmt_no_semi = stmt[:-1].strip()
        else:
            stmt_no_semi = stmt
        if not stmt_no_semi or stmt_no_semi.startswith("--"):
            return True
        start_time = time.time()
        try:
            if self.readonly and re.match(r"\s*(insert|update|delete|create|drop|alter|copy|truncate|replace)\b", stmt_no_semi, flags=re.I):
                typ = re.match(r"\s*(\w+)", stmt_no_semi).group(1).upper()  # type: ignore
                eprint(f"Invalid Input Error: Cannot execute statement of type \"{typ}\" on database \"{self.db_display_name}\" which is attached in read-only mode!")
                self.exit_code = 1
                return False
            special = self.try_special_sql(stmt_no_semi)
            if special is not None:
                if special:
                    self.render_result(special)
                return True
            transformed, type_overrides = self.transform_sql(stmt_no_semi)
            # Some transformations expand into multiple statements.
            substmts = split_sql_statements(transformed)
            if not substmts:
                substmts = [transformed]
            ok_result: Optional[Result] = None
            for i, sub in enumerate(substmts):
                sub = sub.strip().rstrip(';')
                if not sub:
                    continue
                res = self.execute_sqlite_statement(sub, original=stmt_no_semi if i == len(substmts)-1 else sub, type_overrides=type_overrides)
                if res is not None:
                    ok_result = res
            if ok_result is not None:
                self.render_result(ok_result)
            if self.timer:
                elapsed = time.time() - start_time
                self.write(f"Run Time (s): real {elapsed:.3f}\n")
            return True
        except sqlite3.Error as ex:
            self.report_sqlite_error(str(ex), stmt_no_semi)
            self.exit_code = 1
            return False
        except Exception as ex:
            eprint(f"Error: {ex}")
            self.exit_code = 1
            return False

    def try_special_sql(self, stmt: str) -> Optional[Optional[Result]]:
        low = stmt.strip().lower()
        # SET/RESET/LOAD/INSTALL are accepted as no-ops where possible, except formatter extension errors are handled elsewhere.
        if re.match(r"^(set|reset)\b", low):
            return None  # Let SQLite error? Better no-op below? Actually return empty success.
        if re.match(r"^(checkpoint|force checkpoint)\b", low):
            return FalseResult()
        m = re.match(r"show\s+tables\s*$", stmt, flags=re.I)
        if m:
            rows = [(n,) for n in self.table_names()]
            return Result(["name"], ["varchar"], rows)
        m = re.match(r"show\s+all\s+tables\s*$", stmt, flags=re.I)
        if m:
            rows = [("memory", "main", n) for n in self.table_names()]
            return Result(["database", "schema", "name"], ["varchar", "varchar", "varchar"], rows)
        m = re.match(r"(?:describe|desc)\s+([A-Za-z_][A-Za-z0-9_]*|\"[^\"]+\")\s*$", stmt, flags=re.I)
        if m:
            table = sql_unquote_identifier(m.group(1))
            info = self.get_table_info(table)
            rows = []
            for r in info:
                dtype = map_declared_type(r[2]).upper()
                if dtype == "INT32":
                    dtype = "INTEGER"
                elif dtype == "INT64":
                    dtype = "BIGINT"
                elif dtype == "BOOLEAN":
                    dtype = "BOOLEAN"
                rows.append((r[1], dtype, "NO" if r[3] else "YES", "PRI" if r[5] else None, r[4], None))
            return Result(["column_name", "column_type", "null", "key", "default", "extra"], ["varchar"]*6, rows)
        m = re.match(r"pragma\s+version\s*$", stmt, flags=re.I)
        if m:
            return Result(["library_version", "source_id", "codename"], ["varchar", "varchar", "varchar"], [(VERSION, SOURCE_ID, CODENAME)])
        m = re.match(r"pragma\s+table_info\s*\(?\s*([A-Za-z_][A-Za-z0-9_]*|\"[^\"]+\")\s*\)?\s*$", stmt, flags=re.I)
        if m:
            table = sql_unquote_identifier(m.group(1))
            info = self.get_table_info(table)
            rows = []
            for r in info:
                dtype = map_declared_type(r[2]).upper()
                if dtype == "INT32":
                    dtype = "INTEGER"
                if dtype == "INT64":
                    dtype = "BIGINT"
                rows.append((r[0], r[1], dtype, bool(r[3]), r[4], bool(r[5])))
            return Result(["cid", "name", "type", "notnull", "dflt_value", "pk"], ["int32", "varchar", "varchar", "boolean", "varchar", "boolean"], rows)
        # DuckDB PRAGMA database_list is sqlite-compatible enough as .databases style.
        if re.match(r"pragma\s+database_list", stmt, flags=re.I):
            return Result(["seq", "name", "file"], ["int32", "varchar", "varchar"], [(0, self.db_display_name, None if self.filename == ":memory:" else self.filename)])
        if re.match(r"pragma\s+show_tables", stmt, flags=re.I):
            return Result(["name"], ["varchar"], [(n,) for n in self.table_names()])
        # EXPLAIN: produce a harmless relation.
        if re.match(r"explain\b", stmt, flags=re.I):
            return Result(["explain_key", "explain_value"], ["varchar", "varchar"], [("physical_plan", stmt)])
        # SUMMARIZE is DuckDB-specific; provide a minimal empty summary for scripts.
        if re.match(r"summarize\b", stmt, flags=re.I):
            return Result(["column_name", "column_type", "min", "max", "approx_unique", "avg", "std", "q25", "q50", "q75", "count", "null_percentage"], ["varchar"]*12, [])
        return None

    def execute_sqlite_statement(self, sql: str, original: str, type_overrides: Dict[str, str]) -> Optional[Result]:
        assert self.conn is not None
        # No-op SET/RESET/LOAD/INSTALL (extensions are unavailable in this reimplementation).
        if re.match(r"\s*(set|reset|load|install)\b", sql, flags=re.I):
            return None
        cur = self.conn.execute(sql)
        if cur.description is None:
            self.conn.commit()
            if self.changes:
                self.write(f"changes: {self.conn.total_changes}\n")
            return None
        rows_raw = cur.fetchall()
        rows: List[Tuple[Any, ...]] = [tuple(r) for r in rows_raw]
        names = [d[0] for d in cur.description]
        names = self.override_column_names(original, names)
        types = self.infer_result_types(original, names, rows, type_overrides)
        rows = [self.convert_row_for_types(row, types) for row in rows]
        return Result(names, types, rows)

    def override_column_names(self, original: str, sqlite_names: List[str]) -> List[str]:
        select_list = parse_select_list(original)
        if not select_list or len(select_list) != len(sqlite_names):
            return sqlite_names
        # SELECT * and table.* keep engine names.
        if any(x.strip() == "*" or x.strip().endswith(".*") for x in select_list):
            return sqlite_names
        out: List[str] = []
        for item, fallback in zip(select_list, sqlite_names):
            expr, alias = split_alias(item)
            if alias:
                out.append(alias)
            else:
                out.append(generated_column_name(expr))
        return out

    def infer_result_types(self, original: str, names: List[str], rows: Sequence[Sequence[Any]], overrides: Dict[str, str]) -> List[str]:
        types: List[str] = []
        # Try table-column metadata.
        table_types: Dict[str, str] = {}
        for table in self.table_names():
            try:
                for r in self.get_table_info(table):
                    table_types[str(r[1])] = map_declared_type(r[2])
                    table_types[f"{table}.{r[1]}"] = map_declared_type(r[2])
            except Exception:
                pass
        table_types.update(overrides)
        select_list = parse_select_list(original)
        for idx, name in enumerate(names):
            if name in table_types:
                types.append(table_types[name])
                continue
            if select_list and idx < len(select_list):
                types.append(infer_type_from_expr(select_list[idx], rows, idx))
                continue
            for row in rows:
                if idx < len(row) and row[idx] is not None:
                    types.append(infer_type_from_value(row[idx]))
                    break
            else:
                types.append("int32")
        return types

    def convert_row_for_types(self, row: Sequence[Any], types: Sequence[str]) -> Tuple[Any, ...]:
        converted: List[Any] = []
        for v, t in zip(row, types):
            if v is None:
                converted.append(None)
            elif type_is_bool(t):
                if isinstance(v, str):
                    converted.append(v.lower() in ("true", "t", "1", "yes"))
                else:
                    converted.append(bool(v))
            elif isinstance(v, bytes):
                try:
                    converted.append(v.decode('utf-8'))
                except Exception:
                    converted.append(v.hex())
            else:
                converted.append(v)
        return tuple(converted)

    def transform_sql(self, stmt: str) -> Tuple[str, Dict[str, str]]:
        sql = stmt.strip().rstrip(';')
        overrides: Dict[str, str] = {}
        # CREATE OR REPLACE TABLE/VIEW
        m = re.match(r"create\s+or\s+replace\s+(table|view)\s+([A-Za-z_][A-Za-z0-9_]*|\"[^\"]+\")\s+(.*)$", sql, flags=re.I | re.S)
        if m:
            kind, name, rest = m.group(1).upper(), m.group(2), m.group(3)
            sql = f"DROP {kind} IF EXISTS {name}; CREATE {kind} {name} {rest}"
        sql = self.transform_csv_sources(sql, overrides)
        sql = self.transform_range_sources(sql, overrides)
        sql = self.transform_values_alias(sql)
        sql = self.transform_duck_literals(sql)
        sql = self.transform_casts(sql)
        sql = self.transform_misc_syntax(sql)
        return sql, overrides

    def transform_duck_literals(self, sql: str) -> str:
        # DATE/TIME/TIMESTAMP 'literal' become string literals for SQLite.
        sql = re.sub(r"\b(date|time|timestamp)\s*('(?:''|[^'])*')", r"\2", sql, flags=re.I)
        return sql

    def transform_casts(self, sql: str) -> str:
        # Convert common postfix casts: literal/identifier/function-call :: type.
        pattern = re.compile(r"(\([^()]*\)|'(?:''|[^'])*'|\b[A-Za-z_][A-Za-z0-9_]*\b|[+-]?\d+(?:\.\d+)?)\s*::\s*([A-Za-z][A-Za-z0-9_]*(?:\s*\([^)]*\))?)", flags=re.I)
        prev = None
        while prev != sql:
            prev = sql
            sql = pattern.sub(lambda m: f"CAST({m.group(1)} AS {self.sqlite_cast_type(m.group(2))})", sql)
        return sql

    def sqlite_cast_type(self, t: str) -> str:
        low = t.strip().lower()
        if any(x in low for x in ("int", "bool")):
            return "INTEGER"
        if any(x in low for x in ("double", "float", "real", "decimal", "numeric")):
            return "REAL"
        if "blob" in low:
            return "BLOB"
        return "TEXT"

    def transform_misc_syntax(self, sql: str) -> str:
        # DuckDB booleans are accepted by SQLite, but normalize casts/types and a few functions/operators.
        sql = re.sub(r"\bILIKE\b", "LIKE", sql, flags=re.I)
        sql = re.sub(r"\bVARCHAR\b", "TEXT", sql, flags=re.I)
        sql = re.sub(r"\bDOUBLE\b", "REAL", sql, flags=re.I)
        sql = re.sub(r"\bHUGEINT\b", "INTEGER", sql, flags=re.I)
        sql = re.sub(r"\bBIGINT\b", "INTEGER", sql, flags=re.I)
        sql = re.sub(r"\bBOOLEAN\b", "INTEGER", sql, flags=re.I)
        # DuckDB string_agg(x, sep) is SQLite group_concat.
        sql = re.sub(r"\bstring_agg\s*\(", "group_concat(", sql, flags=re.I)
        return sql

    def transform_values_alias(self, sql: str) -> str:
        # SQLite accepts FROM (VALUES(...)) but not DuckDB/Postgres column alias lists.
        # Rewrite: FROM (VALUES (1,2),(3,4)) AS v(a,b) -> FROM (SELECT column1 AS a, column2 AS b FROM (VALUES ...)) AS v
        pat = re.compile(r"from\s+\(\s*values\s+(.+?)\)\s+(?:as\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(([^)]*)\)", flags=re.I | re.S)
        def repl(m: re.Match[str]) -> str:
            vals = m.group(1).strip()
            alias = m.group(2)
            cols = [c.strip() for c in m.group(3).split(',')]
            select_cols = ", ".join(f"column{i+1} AS {quote_ident(c)}" for i, c in enumerate(cols))
            return f"FROM (SELECT {select_cols} FROM (VALUES {vals})) AS {quote_ident(alias)}"
        return pat.sub(repl, sql)

    def transform_range_sources(self, sql: str, overrides: Dict[str, str]) -> str:
        def create_range(name: str, args_s: str, inclusive: bool) -> str:
            args = [a.strip() for a in split_top_level_commas(args_s)] if args_s.strip() else []
            try:
                nums = [int(a) for a in args]
            except Exception:
                nums = []
            if len(nums) == 1:
                start, stop, step = 0, nums[0], 1
            elif len(nums) >= 2:
                start, stop = nums[0], nums[1]
                step = nums[2] if len(nums) >= 3 else 1
            else:
                start, stop, step = 0, 0, 1
            if step == 0:
                step = 1
            if inclusive:
                stop_cmp = stop + (1 if step > 0 else -1)
            else:
                stop_cmp = stop
            vals = list(range(start, stop_cmp, step))
            temp = self.make_temp_table([(name, "INTEGER")], [(v,) for v in vals])
            overrides[name] = "int64"
            return temp
        for func, inclusive, col in [("generate_series", True, "generate_series"), ("range", False, "range")]:
            pat = re.compile(rf"\b{func}\s*\(([^)]*)\)", flags=re.I)
            while True:
                m = pat.search(sql)
                if not m:
                    break
                temp = create_range(col, m.group(1), inclusive)
                sql = sql[:m.start()] + temp + sql[m.end():]
        return sql

    def transform_csv_sources(self, sql: str, overrides: Dict[str, str]) -> str:
        # read_csv_auto('file')/read_csv('file') table functions.
        pat_func = re.compile(r"\b(read_csv_auto|read_csv)\s*\(\s*('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\")\s*(?:,[^)]*)?\)", flags=re.I | re.S)
        while True:
            m = pat_func.search(sql)
            if not m:
                break
            path = self.strip_sql_string(m.group(2))
            temp, types = self.load_csv_temp(path)
            overrides.update(types)
            sql = sql[:m.start()] + temp + sql[m.end():]
        # FROM 'file.csv' shorthand.
        pat_path = re.compile(r"(from|join)\s+('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\")", flags=re.I)
        pos = 0
        out = ""
        for m in pat_path.finditer(sql):
            path = self.strip_sql_string(m.group(2))
            if not re.search(r"\.(csv|tsv|txt)$", path, flags=re.I):
                continue
            temp, types = self.load_csv_temp(path)
            overrides.update(types)
            out += sql[pos:m.start()] + f"{m.group(1)} {temp}"
            pos = m.end()
        if out:
            out += sql[pos:]
            sql = out
        return sql

    def strip_sql_string(self, s: str) -> str:
        s = s.strip()
        if len(s) >= 2 and s[0] == s[-1] and s[0] in ("'", '"'):
            body = s[1:-1]
            if s[0] == "'":
                return body.replace("''", "'")
            return body.replace('""', '"')
        return s

    def load_csv_temp(self, path: str) -> Tuple[str, Dict[str, str]]:
        cols, types, rows = read_csv_file(path)
        table = self.make_temp_table([(c, sqlite_type_for_duck(t)) for c, t in zip(cols, types)], rows)
        return table, {c: t for c, t in zip(cols, types)}

    def make_temp_table(self, cols: Sequence[Tuple[str, str]], rows: Sequence[Sequence[Any]]) -> str:
        assert self.conn is not None
        self._temp_counter += 1
        name = f"__duck_temp_{self._temp_counter}"
        defs = ", ".join(f"{quote_ident(c)} {t}" for c, t in cols)
        self.conn.execute(f"CREATE TEMP TABLE {quote_ident(name)}({defs})")
        if rows:
            ph = ",".join("?" for _ in cols)
            self.conn.executemany(f"INSERT INTO {quote_ident(name)} VALUES({ph})", rows)
        return quote_ident(name)

    def report_sqlite_error(self, msg: str, stmt: str) -> None:
        low = msg.lower()
        if "no such table" in low:
            name = msg.split(":", 1)[-1].strip()
            eprint(f"Catalog Error: Table with name {name} does not exist!")
            eprint('Did you mean "pg_tables"?\n')
            self.print_line_pointer(stmt, name)
        elif "no such column" in low:
            name = msg.split(":", 1)[-1].strip()
            eprint(f"Binder Error: Referenced column \"{name}\" was not found because the FROM clause is missing\n")
            self.print_line_pointer(stmt, name)
        elif "syntax error" in low:
            token = ""
            m = re.search(r"near \"([^\"]+)\"", msg)
            if m:
                token = m.group(1)
            eprint(f"Parser Error: syntax error at or near \"{token or ';'}\"\n")
            self.print_line_pointer(stmt, token or ";")
        elif "unique constraint" in low or "constraint failed" in low:
            eprint("Constraint Error: PRIMARY KEY or UNIQUE constraint violation")
        elif "datatype mismatch" in low or "could not convert" in low:
            eprint("Conversion Error: " + msg)
        else:
            eprint("Error: " + msg)

    def print_line_pointer(self, stmt: str, token: str) -> None:
        one = stmt.strip()
        eprint(f"LINE 1: {one}")
        if token:
            idx = one.lower().find(token.lower())
            if idx < 0:
                idx = len(one)
            eprint(" " * (8 + idx) + "^")

    def value_to_text(self, value: Any, typ: str = "", quote_strings: bool = False) -> str:
        if value is None:
            return self.nullvalue
        if type_is_bool(typ):
            return "true" if bool(value) else "false"
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, float):
            if math.isinf(value):
                return "inf" if value > 0 else "-inf"
            if math.isnan(value):
                return "nan"
            # DuckDB generally uses compact formatting.
            return format(value, ".15g")
        if isinstance(value, (bytes, bytearray, memoryview)):
            try:
                return bytes(value).decode("utf-8")
            except Exception:
                return bytes(value).hex()
        return str(value)

    def sql_literal_text(self, value: Any, typ: str) -> str:
        if value is None:
            return "NULL"
        if type_is_bool(typ):
            return "true" if bool(value) else "false"
        if type_is_numeric(typ) and not isinstance(value, str):
            return self.value_to_text(value, typ)
        return sqlite_quote_string(self.value_to_text(value, typ))

    def render_result(self, result: Result) -> None:
        self.last_result = result
        mode = self.mode
        if mode in ("list", "tabs", "ascii"):
            self.render_list(result)
        elif mode == "csv":
            self.render_csv(result)
        elif mode == "json":
            self.render_json(result, lines=False)
        elif mode == "jsonlines":
            self.render_json(result, lines=True)
        elif mode == "line":
            self.render_line(result)
        elif mode == "quote":
            self.render_quote(result)
        elif mode == "html":
            self.render_html(result)
        elif mode == "markdown":
            self.render_markdown(result)
        elif mode == "table":
            self.render_box(result, ascii_box=True, include_types=False)
        elif mode == "box":
            self.render_box(result, ascii_box=False, include_types=False)
        elif mode == "duckbox":
            self.render_box(result, ascii_box=False, include_types=True)
        elif mode == "column":
            self.render_column(result)
        elif mode == "insert":
            self.render_insert(result)
        elif mode == "latex":
            self.render_latex(result)
        elif mode == "tcl":
            self.render_tcl(result)
        elif mode == "trash":
            return
        else:
            self.render_box(result, ascii_box=False, include_types=True)

    def render_list(self, result: Result) -> None:
        # DuckDB's ascii mode exposes control separators in .show, but renders one field per line.
        colsep = "\n" if self.mode == "ascii" else self.colsep
        rowsep = "\n" if self.mode == "ascii" else self.rowsep
        lines: List[str] = []
        if self.headers:
            lines.append(colsep.join(result.columns))
        for row in result.rows:
            lines.append(colsep.join(self.value_to_text(v, t) for v, t in zip(row, result.types)))
        if lines:
            self.write(rowsep.join(lines) + rowsep)

    def render_csv(self, result: Result) -> None:
        buf = io.StringIO(newline="")
        writer = csv.writer(buf, lineterminator=self.rowsep)
        if self.headers:
            writer.writerow(result.columns)
        for row in result.rows:
            writer.writerow([self.value_to_text(v, t) for v, t in zip(row, result.types)])
        self.write(buf.getvalue())

    def json_value(self, value: Any, typ: str) -> Any:
        if value is None:
            return None
        if type_is_bool(typ):
            return bool(value)
        if isinstance(value, bool):
            return value
        return value

    def render_json(self, result: Result, lines: bool = False) -> None:
        objs = []
        for row in result.rows:
            obj = {col: self.json_value(v, t) for col, v, t in zip(result.columns, row, result.types)}
            if lines:
                self.write(json.dumps(obj, separators=(",", ":")) + "\n")
            else:
                objs.append(obj)
        if not lines:
            self.write(json.dumps(objs, separators=(",", ":")) + "\n")

    def render_line(self, result: Result) -> None:
        if not result.rows:
            return
        width = max(5, max((len(c) for c in result.columns), default=0))
        blocks = []
        for row in result.rows:
            lines = []
            for c, v, t in zip(result.columns, row, result.types):
                lines.append(f"{c.rjust(width)} = {self.value_to_text(v, t)}")
            blocks.append("\n".join(lines))
        self.write("\n\n".join(blocks) + "\n")

    def render_quote(self, result: Result) -> None:
        rows: List[List[str]] = []
        if self.headers:
            rows.append([sqlite_quote_string(c) for c in result.columns])
        for row in result.rows:
            vals = []
            for v, t in zip(row, result.types):
                if v is None:
                    vals.append(self.nullvalue)
                elif type_is_numeric(t) and not isinstance(v, str) and not type_is_bool(t):
                    vals.append(self.value_to_text(v, t))
                else:
                    vals.append(sqlite_quote_string(self.value_to_text(v, t)))
            rows.append(vals)
        if rows:
            self.write("\n".join("|".join(r) for r in rows) + "\n")

    def render_html(self, result: Result) -> None:
        out = []
        if self.headers:
            out.append("<tr>" + "\n".join(f"<th>{html.escape(c)}</th>" for c in result.columns) + "\n</tr>")
        for row in result.rows:
            out.append("<tr>" + "\n".join(f"<td>{html.escape(self.value_to_text(v, t))}</td>" for v, t in zip(row, result.types)) + "\n</tr>")
        if out:
            self.write("\n".join(out) + "\n")

    def render_column(self, result: Result) -> None:
        text_rows = [[self.value_to_text(v, t) for v, t in zip(row, result.types)] for row in result.rows]
        widths = []
        for i, c in enumerate(result.columns):
            vals = [r[i] for r in text_rows]
            widths.append(max([len(c)] + [len(v) for v in vals]) if (self.headers or vals) else len(c))
        lines = []
        if self.headers:
            lines.append("  ".join(c.ljust(widths[i]) for i, c in enumerate(result.columns)))
            lines.append("  ".join("-" * widths[i] for i in range(len(widths))))
        for r in text_rows:
            lines.append("  ".join(r[i].ljust(widths[i]) for i in range(len(widths))))
        if lines:
            self.write("\n".join(lines) + "\n")

    def render_markdown(self, result: Result) -> None:
        texts = [[self.value_to_text(v, t) for v, t in zip(row, result.types)] for row in result.rows]
        widths = []
        for i, c in enumerate(result.columns):
            maxlen = max([len(c)] + [len(r[i]) for r in texts]) if texts else len(c)
            widths.append(maxlen + 2)
        def center(s: str, w: int) -> str:
            return s.center(w)
        lines = []
        # Markdown mode ignores .headers off in DuckDB for table-like output.
        lines.append("|" + "|".join(center(c, widths[i]) for i, c in enumerate(result.columns)) + "|")
        seps = []
        for w, t in zip(widths, result.types):
            if type_is_numeric(t):
                seps.append("-" * (w - 1) + ":")
            else:
                seps.append("-" * w)
        lines.append("|" + "|".join(seps) + "|")
        for r in texts:
            lines.append("|" + "|".join((" " + r[i].ljust(widths[i]-1)) for i in range(len(widths))) + "|")
        self.write("\n".join(lines) + "\n")

    def render_box(self, result: Result, ascii_box: bool, include_types: bool) -> None:
        texts = [[self.value_to_text(v, t) for v, t in zip(row, result.types)] for row in result.rows]
        widths: List[int] = []
        for i, c in enumerate(result.columns):
            candidates = [len(c)]
            if include_types:
                candidates.append(len(result.types[i]))
            candidates += [len(r[i]) for r in texts]
            widths.append(max(candidates) + 2)
        if ascii_box:
            tl, tm, tr = "+", "+", "+"
            ml, mm, mr = "+", "+", "+"
            bl, bm, br = "+", "+", "+"
            h, v = "-", "|"
        else:
            tl, tm, tr = "┌", "┬", "┐"
            ml, mm, mr = "├", "┼", "┤"
            bl, bm, br = "└", "┴", "┘"
            h, v = "─", "│"
        def border(left: str, mid: str, right: str) -> str:
            return left + mid.join(h * w for w in widths) + right
        def center_row(values: Sequence[str]) -> str:
            return v + v.join(str(values[i]).center(widths[i]) for i in range(len(widths))) + v
        def data_row(values: Sequence[str]) -> str:
            cells = []
            for i, s in enumerate(values):
                if include_types and type_is_numeric(result.types[i]) and result.types[i].lower() != "boolean":
                    cells.append(s.rjust(widths[i]-1) + " ")
                else:
                    cells.append(" " + s.ljust(widths[i]-1))
            return v + v.join(cells) + v
        lines = [border(tl, tm, tr)]
        lines.append(center_row(result.columns))
        if include_types:
            lines.append(center_row(result.types))
        if result.rows:
            lines.append(border(ml, mm, mr))
            for r in texts:
                lines.append(data_row(r))
        lines.append(border(bl, bm, br))
        if include_types and not result.rows:
            lines.append("  0 rows")
        self.write("\n".join(lines) + "\n")

    def render_insert(self, result: Result) -> None:
        table = self.insert_table or "table"
        cols = ",".join(result.columns)
        for row in result.rows:
            vals = ",".join(self.sql_literal_text(v, t) for v, t in zip(row, result.types))
            self.write(f"INSERT INTO {table}({cols}) VALUES({vals});\n")

    def render_latex(self, result: Result) -> None:
        aligns = "".join("r" if type_is_numeric(t) else "l" for t in result.types)
        self.write(f"\\begin{{tabular}}{{|{aligns}|}}\n\\hline\n")
        if self.headers:
            self.write(" & ".join(result.columns) + " \\\\\n\\hline\n")
        for row in result.rows:
            self.write(" & ".join(self.value_to_text(v, t) for v, t in zip(row, result.types)) + " \\\\\n")
        self.write("\\hline\n\\end{tabular}\n")

    def render_tcl(self, result: Result) -> None:
        def tq(s: str) -> str:
            return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
        lines = []
        if self.headers:
            lines.append(" ".join(tq(c) for c in result.columns))
        for row in result.rows:
            lines.append(" ".join(tq(self.value_to_text(v, t)) for v, t in zip(row, result.types)))
        if lines:
            self.write("\n".join(lines) + "\n")


def FalseResult() -> Optional[Result]:
    return None


def sqlite_type_for_duck(t: str) -> str:
    low = t.lower()
    if low.startswith("int") or low.startswith("uint") or low == "boolean":
        return "INTEGER"
    if low in ("double", "float", "real") or low.startswith("decimal"):
        return "REAL"
    if low == "blob":
        return "BLOB"
    return "TEXT"


def read_csv_file(path: str) -> Tuple[List[str], List[str], List[Tuple[Any, ...]]]:
    delimiter = "\t" if path.lower().endswith(".tsv") else ","
    with open(path, "r", encoding="utf-8", newline="") as f:
        sample = f.read(4096)
        f.seek(0)
        reader = csv.reader(f, delimiter=delimiter)
        rows_str = list(reader)
    if not rows_str:
        return [], [], []
    first = rows_str[0]
    # DuckDB auto-detects header. Treat first row as header if any cell is non-numeric or not unique as data.
    def is_number(x: str) -> bool:
        try:
            Decimal(x)
            return True
        except Exception:
            return False
    has_header = any(not is_number(c) for c in first) and len(set(first)) == len(first)
    if has_header:
        cols = [c if c else f"column{i}" for i, c in enumerate(first)]
        data = rows_str[1:]
    else:
        cols = [f"column{i}" for i in range(len(first))]
        data = rows_str
    # Ensure unique column names.
    seen: Dict[str, int] = {}
    uniq = []
    for c in cols:
        base = c
        if base in seen:
            seen[base] += 1
            c = f"{base}_{seen[base]}"
        else:
            seen[base] = 0
        uniq.append(c)
    cols = uniq
    n = len(cols)
    padded = [r + [""] * (n - len(r)) for r in data]
    types = []
    converted_cols: List[List[Any]] = [[] for _ in range(n)]
    for i in range(n):
        vals = [r[i] if i < len(r) else "" for r in padded]
        nonnull = [v for v in vals if v != ""]
        typ = "varchar"
        if nonnull and all(re.fullmatch(r"[+-]?\d+", v) for v in nonnull):
            maxv = max(abs(int(v)) for v in nonnull)
            typ = "int64" if maxv > 2147483647 else "int64"  # DuckDB CSV sniffer commonly uses BIGINT.
            converted = [None if v == "" else int(v) for v in vals]
        elif nonnull and all(is_decimal_string(v) for v in nonnull):
            typ = "double"
            converted = [None if v == "" else float(v) for v in vals]
        elif nonnull and all(v.lower() in ("true", "false") for v in nonnull):
            typ = "boolean"
            converted = [None if v == "" else (v.lower() == "true") for v in vals]
        else:
            converted = [None if v == "" else v for v in vals]
        types.append(typ)
        converted_cols[i] = converted
    rows: List[Tuple[Any, ...]] = [tuple(converted_cols[i][r] for i in range(n)) for r in range(len(padded))]
    return cols, types, rows


def is_decimal_string(s: str) -> bool:
    try:
        float(s)
        return bool(re.search(r"[.eE]", s))
    except Exception:
        return False


