def format_extension_error(prog: str) -> None:
    eprint(f"{prog}: Catalog Error: Scalar Function with name \"duckdb_format_sql\" is not in the catalog, but it exists in the autocomplete extension.\n")
    eprint("Please try installing and loading the autocomplete extension by running:")
    eprint("INSTALL autocomplete;")
    eprint("LOAD autocomplete;\n")
    eprint("Alternatively, consider enabling auto-install and auto-load by running:")
    eprint("SET autoinstall_known_extensions=1;")
    eprint("SET autoload_known_extensions=1;")


def unknown_option(prog: str, opt: str) -> int:
    suggestions = {
        "--help": "-help",
        "-no-such-flag": "-c",
    }
    eprint(f"Unknown Option Error: Unrecognized option '{opt}'\n")
    if opt in suggestions:
        eprint(f"Did you mean: \"{suggestions[opt]}\"")
    else:
        eprint('Did you mean: "-c"')
    eprint(f"Run '{prog} -help' for a list of options.\n")
    return 1


def parse_and_run(argv: List[str]) -> int:
    prog = argv[0] if argv else "./executable"
    # DuckDB accepts --help/--version even though help lists single dash.
    if len(argv) >= 2 and argv[1] in ("-h", "-help", "--help"):
        print_cli_help(prog)
        return 0
    if len(argv) >= 2 and argv[1] in ("-version", "--version"):
        print(VERSION_LINE)
        return 0
    if len(argv) >= 2 and argv[1] in ("-format", "--format"):
        # The provided build lacks the autocomplete formatter extension; mimic that observed behavior.
        _ = sys.stdin.read()
        format_extension_error(prog)
        return 0
    if len(argv) >= 3 and argv[1] in ("-format-file", "--format-file"):
        try:
            open(argv[2], "r", encoding="utf-8").read()
        except Exception:
            pass
        format_extension_error(prog)
        return 0

    shell = DuckShell()
    commands_to_run: List[str] = []
    files_to_run: List[str] = []
    no_stdin = False
    positional: List[str] = []
    init_files: List[str] = []

    i = 1
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "-help", "--help"):
            print_cli_help(prog)
            return 0
        if a in ("-version", "--version"):
            print(VERSION_LINE)
            return 0
        if a in ("-ascii", "-box", "-column", "-csv", "-html", "-json", "-jsonlines", "-line", "-list", "-markdown", "-quote", "-table"):
            shell.set_mode(a[1:].lower(), from_cli=True)
        elif a == "-bail":
            shell.bail = True
        elif a == "-batch":
            shell.batch = True
        elif a == "-interactive":
            shell.interactive_forced = True
        elif a == "-echo":
            shell.echo = True
        elif a in ("-header", "-headers"):
            shell.headers = True
        elif a in ("-noheader", "-noheaders"):
            shell.headers = False
        elif a == "-safe":
            shell.safe = True
        elif a == "-readonly":
            shell.readonly = True
            # Reopen current DB read-only only if a filename has already been selected.
            if shell.filename != ":memory:":
                shell.open_database(shell.filename)
        elif a == "-no-init":
            shell.no_init = True
        elif a == "-no-stdin":
            no_stdin = True
        elif a in ("-unsigned", "-unredacted", "-ui"):
            if a == "-ui":
                eprint("Error: UI extension is not available")
                return 1
            # accepted no-op
        elif a == "-storage-version":
            i += 1
            if i >= len(argv):
                return unknown_option(prog, a)
        elif a in ("-separator", "-newline", "-nullvalue", "-cmd", "-c", "-s", "-f", "-init", "-format-file"):
            i += 1
            if i >= len(argv):
                eprint(f"Missing argument for {a}")
                return 1
            val = argv[i]
            if a == "-separator":
                shell.colsep = shell.decode_cli_sep(val)
            elif a == "-newline":
                shell.rowsep = shell.decode_cli_sep(val)
            elif a == "-nullvalue":
                shell.nullvalue = val
            elif a == "-cmd":
                # Execute option commands in order, as observed.
                if shell.echo:
                    shell.write(val + "\n")
                if val.lstrip().startswith('.'):
                    shell.execute_dot_command(val.strip())
                else:
                    shell.process_script(val)
            elif a in ("-c", "-s"):
                commands_to_run.append(val)
                no_stdin = True
            elif a == "-f":
                files_to_run.append(val)
                no_stdin = True
            elif a == "-init":
                if not shell.no_init:
                    init_files.append(val)
            elif a == "-format-file":
                format_extension_error(prog)
                return 0
        elif a == "-format":
            _ = sys.stdin.read()
            format_extension_error(prog)
            return 0
        elif a.startswith('-'):
            return unknown_option(prog, a)
        else:
            positional.append(a)
        i += 1

    if positional:
        # First positional is database filename; second (if any) is SQL.
        shell.open_database(positional[0])
        if len(positional) > 1:
            commands_to_run.append(" ".join(positional[1:]))
            no_stdin = True

    if shell.no_init:
        init_files = []
    for path in init_files:
        try:
            eprint(f"{GREY}-- Loading resources from {path}{RESET}")
            with open(path, "r", encoding="utf-8") as f:
                shell.process_script(f.read(), path)
        except Exception as ex:
            eprint(f"Error: cannot open init file {path}: {ex}")
            shell.exit_code = 1
            if shell.bail:
                return shell.exit_code

    for fpath in files_to_run:
        try:
            with open(fpath, "r", encoding="utf-8") as f:
                shell.process_script(f.read(), fpath)
        except Exception as ex:
            eprint(f"Error: cannot open \"{fpath}\": {ex}")
            shell.exit_code = 1
            if shell.bail:
                return shell.exit_code

    for cmd in commands_to_run:
        if shell.echo:
            shell.write(cmd.strip() + "\n")
        shell.process_script(cmd)
        if shell.bail and shell.exit_code:
            return shell.exit_code

    if not no_stdin and not shell.should_exit:
        interactive = shell.interactive_forced or (sys.stdin.isatty() and not shell.batch)
        if interactive:
            run_interactive(shell)
        else:
            data = sys.stdin.read()
            if data:
                shell.process_script(data)
    try:
        if shell.conn is not None:
            shell.conn.commit()
    except Exception:
        pass
    return shell.exit_code


def run_interactive(shell: DuckShell) -> None:
    sys.stdout.write(f"DuckDB {VERSION} ({CODENAME})\n")
    sys.stdout.write(f"{GREY}Enter \".help\" for usage hints.\n{RESET}")
    sys.stdout.flush()
    buf = ""
    while not shell.should_exit:
        prompt = f"{BOLD}{ORANGE}{shell.db_display_name}{RESET} D " if not buf else "   ...> "
        try:
            line = input(prompt)
        except EOFError:
            break
        if not buf and line.lstrip().startswith('.'):
            if shell.echo:
                shell.write(line + "\n")
            shell.execute_dot_command(line.strip())
            continue
        buf += line + "\n"
        if line.strip().endswith(';'):
            shell.process_script(buf)
            buf = ""
    if buf.strip():
        shell.process_script(buf)


def main() -> None:
    try:
        rc = parse_and_run(sys.argv)
    except BrokenPipeError:
        rc = 0
    sys.exit(rc)


if __name__ == "__main__":
    main()
